/// Singleton entity holding the global physics parameters a world is seeded with. These three are what KGModule::seedPhysicsConstants writes; they were undeclared properties until 2026-08-13. This is per-world KG configuration, not the solver constants registry: those are build-time inputs generated into the engine (INV-29), and the solver never reads the KG.
struct PhysicsConstants : public Entity {
    /// Gravitational acceleration along world Z, m/s2. Negative points down. Earth default -9.8. The world-Z framing is legacy: this is a seed value for a world, not a licence for solver code to assume an up axis, which INV-6 forbids.
    std::optional<float> gravity_z = std::nullopt;
    /// Global air drag coefficient, dimensionless. 0 disables it, which is the current default.
    std::optional<float> air_resistance = std::nullopt;
    /// Coulomb friction coefficient used where a pair declares none, dimensionless. Default 0.5.
    std::optional<float> default_friction = std::nullopt;
};


/// Physics constraint between two particles.
struct Constraint : public Entity {
    GluonType gluon_type = {};
    /// Constraint stiffness in N/m.
    float stiffness = {};
    /// Damping coefficient in Ns/m.
    std::optional<float> damping = std::nullopt;
    /// Force threshold for constraint failure.
    std::optional<float> breaking_force = std::nullopt;
    /// Stable KGParticleID of the first constraint endpoint.
    std::optional<int32_t> particle_a = std::nullopt;
    /// Stable KGParticleID of the second constraint endpoint.
    std::optional<int32_t> particle_b = std::nullopt;
    /// Rest length of the constraint in meters.
    std::optional<float> rest_distance = std::nullopt;
    /// Undamaged stiffness in N/m as serialized by the generators. Sibling of the required `stiffness` slot; the generators write this key today (schema/writer drift, noted by Malleus H1).
    std::optional<float> base_stiffness = std::nullopt;
    /// Semantic joint name (e.g. left_hip) when the constraint is a skeletal joint.
    std::optional<std::string> joint_name = std::nullopt;
    /// Owning-entity back-reference the totem generator serializes on its constraints. Relation-shaped data stored as a property; declared as written (Malleus H1), migration to a real relation is follow-up work.
    std::optional<int32_t> entity_id = std::nullopt;
    /// Attachment offset of endpoint A, local X, meters.
    std::optional<float> offset_a_x = std::nullopt;
    /// Attachment offset of endpoint A, local Y, meters.
    std::optional<float> offset_a_y = std::nullopt;
    /// Attachment offset of endpoint A, local Z, meters.
    std::optional<float> offset_a_z = std::nullopt;
    /// Attachment offset of endpoint B, local X, meters.
    std::optional<float> offset_b_x = std::nullopt;
    /// Attachment offset of endpoint B, local Y, meters.
    std::optional<float> offset_b_y = std::nullopt;
    /// Attachment offset of endpoint B, local Z, meters.
    std::optional<float> offset_b_z = std::nullopt;
};


/// Declares how particles carrying this profile interact with other particles: a category bit and a collides-with mask consulted at contact broad phase, plus optional medium parameters (drag, buoyancy, directional field force) applied to particles overlapping a filtered pair. Profile 0 is the engine default: collide with everything, no medium.
struct ParticleInteractionProfile : public Entity {
    /// Which interaction category bit (0-31) this profile occupies.
    std::optional<int32_t> category_bit = std::nullopt;
    /// Bitmask of category bits this profile exchanges rigid contact with.
    std::optional<int32_t> collides_with_mask = std::nullopt;
    /// Medium drag applied to particles inside this profile's volume (0 = none).
    std::optional<float> drag_coefficient = std::nullopt;
    /// Buoyant acceleration share against gravity for intruders (0 = none, 1 = neutral).
    std::optional<float> buoyancy_factor = std::nullopt;
    /// Directional field force X applied to intruders, Newtons.
    std::optional<float> field_fx = std::nullopt;
    /// Directional field force Y applied to intruders, Newtons.
    std::optional<float> field_fy = std::nullopt;
    /// Directional field force Z applied to intruders, Newtons.
    std::optional<float> field_fz = std::nullopt;
};


/// A declarative EVENT rule, executed by the interaction system. Three separable questions, one slot each: `trigger` is which engine event source to listen to (closed), `condition` is whether this occurrence matters (open), `effect` is what to do (open).
/// Event rules are pushed and fire once per episode. They are not the same mechanism as capability response rules, which are state predicates pulled over the KG and safe to re-evaluate; see docs/GAME_LAYER.md for when to reach for which.
struct TransformationRule : public Entity {
    /// WHICH engine event source this rule listens to. Genuinely closed: each value is a queue the interaction system owns, and a game cannot add one without engine code. See TransformationTrigger for the vocabulary and the case-normalization rule.
    std::optional<TransformationTrigger> trigger = std::nullopt;
    /// WHETHER this rule cares about a given occurrence, evaluated against the event context once the trigger has selected it. Open by design: engine built-ins plus anything a game registers. Syntax "<name>" or "<name>:<args>". Empty means unconditional.
    /// Engine built-ins for ON_CONTACT:
    ///   with_type:<EntityType>   the other party resolves to this type
    ///   impact_above:<m/s>       approach speed exceeds a threshold
    ///
    /// This slot generalizes trigger_profile, which is the same idea hardcoded to one comparison. New rules should prefer condition.
    std::optional<std::string> condition = std::nullopt;
    /// WHAT this rule does when it fires. Open by design: the TransformationEffect enum lists the engine built-ins, and a game-registered effect name is an equally legal value here, which is why this slot is a string rather than typed to that enum.
    std::optional<std::string> effect = std::nullopt;
    /// Profile id the effect targets (for swap_profile).
    std::optional<int32_t> target_profile = std::nullopt;
    /// Effect duration in seconds (for timed effects).
    std::optional<float> duration_s = std::nullopt;
    /// Interaction profile id a volume/contact trigger binds to (0 = any profile fires the rule).
    std::optional<int32_t> trigger_profile = std::nullopt;
};


/// Something that happens in the game world.
struct WorldEvent : public Event {
    /// ID of the entity that caused the event.
    std::optional<std::string> source_entity_id = std::nullopt;
    /// ID of the entity affected by the event.
    std::optional<std::string> target_entity_id = std::nullopt;
    /// Event payload keys (parallel to payload_values). Populated from rule.N.payload.* KG properties when emit_event fires.
    std::vector<std::string> payload_keys = {};
    /// Event payload values (parallel to payload_keys).
    std::vector<std::string> payload_values = {};
};


/// Two entities physically collide. Carries the contact itself, not just the fact of it: an event rule can only be as specific as the occurrence it reads, and a consequence (knockback, absorption, where to spawn blood) needs the geometry and the energy.
/// source/target_entity_id name the two creatures; source/target_part_id name the body parts that actually touched, because armour and injury are per-part. The normal comes from contact geometry, never from a world-up assumption, so it is meaningful on walls, ceilings and in zero-g.
struct CollisionEvent : public WorldEvent {
    /// Magnitude of collision impact in Newtons.
    std::optional<float> collision_force = std::nullopt;
    /// Contact normal X, unit, pointing from source toward target.
    std::optional<float> normal_x = std::nullopt;
    /// Contact normal Y, unit, pointing from source toward target.
    std::optional<float> normal_y = std::nullopt;
    /// Contact normal Z, unit, pointing from source toward target.
    std::optional<float> normal_z = std::nullopt;
    /// World-space contact point X.
    std::optional<float> contact_x = std::nullopt;
    /// World-space contact point Y.
    std::optional<float> contact_y = std::nullopt;
    /// World-space contact point Z.
    std::optional<float> contact_z = std::nullopt;
    /// Overlap depth at the contact, metres.
    std::optional<float> penetration = std::nullopt;
    /// Relative velocity along the contact normal, m/s. NEGATIVE means the pair is approaching; positive means separating. This is the energy term a consequence scales with, and the sign convention is the solver's, not a reinterpretation.
    std::optional<float> approach_speed = std::nullopt;
    /// KG EntityID of the body part on the source side, decimal string. Matches the source_entity_id/target_entity_id convention on WorldEvent rather than introducing a second id encoding.
    std::optional<std::string> source_part_id = std::nullopt;
    /// KG EntityID of the body part on the target side, decimal string.
    std::optional<std::string> target_part_id = std::nullopt;
};


